sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 12px;
  margin-bottom: 22px;
}

.wrm-metric {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-soft);
  padding: 14px 16px;
}

.wrm-metric .l {
  font-size: 11px;
  color: var(--ink-3);
}

.wrm-metric .n {
  font-size: 28px;
  line-height: 1.15;
  color: var(--ink);
}
.wrm-metric .n.free { color: var(--free-fg); }
.wrm-metric .n.out  { color: var(--out-fg); }

sp_widget.script:
(function() {

  // Workspaces free to book right now.
  var free = new GlideRecord('x_1903615_worksp_0_workspace_options');
  free.addQuery('status', 'available');
  free.query();
  data.available = free.getRowCount();

  // Workspaces out of service.
  var maint = new GlideRecord('x_1903615_worksp_0_workspace_options');
  maint.addQuery('status', 'under_maintenance');
  maint.query();
  data.maintenance = maint.getRowCount();

  // This user's reservations that haven't finished yet.
  var mine = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  mine.addQuery('reserved_for', gs.getUserID());
  mine.addQuery('reservation_status', 'IN', 'pending_check_in,checked_in');
  mine.query();
  data.upcoming = mine.getRowCount();

})();
